package com.ruoyi.medical.persistence;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.junit.jupiter.api.Test;
import java.util.*;import static com.ruoyi.medical.persistence.FormalEvaluationContextSchemaTest.*;
/** Real 088 context service plus bound-root writer/reader. 083 input/root/scope boundaries are explicit doubles. */
class FormalEvaluationBoundExecutionsTest {
 final FormalEvaluationContextStoreTest f=new FormalEvaluationContextStoreTest();
 final FormalEvaluationExecutionInputs.Prepared inputs=mock(FormalEvaluationExecutionInputs.Prepared.class);final FormalEvaluationExecutionAdmission.Prepared admission=mock(FormalEvaluationExecutionAdmission.Prepared.class);
 final FormalEvaluationExecutionRegistrations roots=mock(FormalEvaluationExecutionRegistrations.class);final FormalEvaluationExecutionScopes scopes=mock(FormalEvaluationExecutionScopes.class);final FormalEvaluationExecutionScopes.Prepared scope=mock(FormalEvaluationExecutionScopes.Prepared.class);
 final FormalEvaluationBoundExecutions service;final String execution=id(200);final FormalEvaluationExecutionRegistrations.Registration registration=new FormalEvaluationExecutionRegistrations.Registration(execution,"a".repeat(64),1,1);final Map<String,Object> root=new LinkedHashMap<>();final FormalEvaluationContextStore.Receipt binding;
 FormalEvaluationBoundExecutionsTest()throws Exception {
  binding=f.author();f.approve(binding);f.actor=id(101);
  when(inputs.requireCurrent(f.a)).thenReturn(admission);var request=new FormalEvaluationExecutionProtocol.Start("1.0.0",id(201),"a".repeat(64),"1",b(2),b(3),b(202),b(203));when(admission.request()).thenReturn(request);when(admission.projectId()).thenReturn(id(1));when(admission.classification()).thenReturn("INTERNAL");when(admission.nodes()).thenReturn(List.of());
  var original=f.json.object();original.set("request",f.json.tree(request));original.set("definition",f.json.tree(null));original.set("nodes",f.json.tree(List.of()));original.set("source_snapshot",f.json.tree(b(204)));original.put("profile_revision",id(205));root.put("tenant_id",f.tenant);root.put("execution_id",execution);root.put("project_id",id(1));root.put("created_by",f.actor);root.put("idempotency_key","bound-original-key");root.put("request_sha256","a".repeat(64));root.put("admission_sha256",org.apache.commons.codec.digest.DigestUtils.sha256Hex(f.json.canonical(original)));root.put("canonical_admission",f.json.canonical(original));f.rows("formal_evaluation_execution").add(root);
  when(roots.register(f.a,"bound-original-key",inputs)).thenReturn(registration);when(roots.requireOriginal(f.a,"bound-original-key",inputs)).thenReturn(registration);when(scopes.read(f.a,inputs,b(204),id(205))).thenReturn(scope);
  when(f.db.query(anyString(),any(org.springframework.jdbc.core.RowMapper.class))).thenReturn(List.of(f.now));service=new FormalEvaluationBoundExecutions(null,null,roots,scopes,f.store,f.schema,f.json,f.db);
 }
 FormalEvaluationExecutionRegistrations.Registration prepare()throws Exception{return f.tx(()->service.prepare(f.a,"bound-original-key",inputs,binding.binding()));}
 @Test void bindsActualPreparedRootToIndependentlyApprovedOriginalContext()throws Exception{assertEquals(registration,prepare());assertEquals(1,f.rows("formal_evaluation_execution_context").size());assertEquals(3,f.rows("audit_event").size());var row=f.rows("formal_evaluation_execution_context").get(0);assertEquals(binding.binding().version_id(),row.get("context_version"));f.tx(()->{var proof=service.require(f.a,execution,inputs);proof.requireUnchanged();assertEquals(binding.binding(),proof.context().binding());return null;});}
 @Test void exactRetryDoesNotCreateSecondBindingOrEvent()throws Exception{prepare();prepare();assertEquals(1,f.rows("formal_evaluation_execution_context").size());assertEquals(3,f.rows("outbox_event").size());}
 @Test void noBindingAfterCellExecutionExists()throws Exception{f.rows("formal_evaluation_cell").add(new LinkedHashMap<>(Map.of("tenant_id",f.tenant,"execution_id",execution,"run_id",id(210))));assertThrows(TenantAccessException.class,this::prepare);assertTrue(f.rows("formal_evaluation_execution_context").isEmpty());}
 @Test void missingBindingOriginalAuditBlocksPrivateProof()throws Exception{prepare();String audit=(String)f.rows("formal_evaluation_execution_context").get(0).get("audit_id");f.rows("audit_event").removeIf(r->audit.equals(r.get("audit_id")));assertThrows(TenantAccessException.class,()->f.tx(()->service.require(f.a,execution,inputs)));}
 @Test void changedPreparedRootHashCannotReuseContextBinding()throws Exception{prepare();root.put("admission_sha256","f".repeat(64));assertThrows(TenantAccessException.class,()->f.tx(()->service.require(f.a,execution,inputs)));}
 @Test void revokedContextApprovalPreventsRootProducerInvocation()throws Exception{when(f.identities.active(any())).thenReturn(false);assertThrows(TenantAccessException.class,this::prepare);verifyNoInteractions(roots);}
 @Test void boundProofCannotCrossScope()throws Exception{prepare();var proof=f.tx(()->service.require(f.a,execution,inputs));assertThrows(TenantAccessException.class,()->f.tx(()->{proof.requireUnchanged();return null;}));}
 @Test void snapshotRereadIsMandatory()throws Exception{prepare();when(scopes.read(f.a,inputs,b(204),id(205))).thenThrow(new TenantAccessException(com.ruoyi.medical.contracts.ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,()->f.tx(()->service.require(f.a,execution,inputs)));}
}
